proPlanningPrompt.responseSchema:
{
  "type": "object",
  "description": "Planner output: user-facing response + optional plan + optional UI",
  "required": ["responseText", "reasoningTrace"],
  "properties": {

    "responseText": {
      "type": "string",
      "description": "User-facing response shown directly to the user. Written in Carrot's voice per the voice module. This is the PRIMARY output."
    },

    "reasoningTrace": {
      "type": "string",
      "description": "Internal reasoning: mode determination, plan decisions, user signals, trade-offs, guardrails applied. NOT user-facing — for logging and audit."
    },

    "uiDirective": {
      "type": "object",
      "description": "Emit when response includes visual content. Null for text-only.",
      "nullable": true,
      "properties": {
        "components": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["componentId", "dataMapping"],
            "properties": {
              "componentId": {
                "type": "string",
                "description": "From componentRegistry."
              },
              "dataMapping": {
                "type": "object",
                "description": "Output keys → component input schema."
              }
            }
          }
        },
        "layoutIntent": {
          "type": "string",
          "enum": ["STACK", "COMPARISON", "SINGLE_FOCUS"]
        },
        "transition": {
          "type": "string",
          "enum": ["APPEND", "REPLACE", "SLIDE_IN"]
        }
      }
    },

    "planObject": {
      "type": "object",
      "description": "Structured plan. Null for MODE 5. Required for MODEs 1-4.",
      "nullable": true,
      "properties": {

        "planId": {
          "type": "string",
          "description": "Descriptive slug: 'ef-setup-v1', 'scenario-city-move-bangalore'."
        },

        "planStatus": {
          "type": "string",
          "enum": ["DRAFT", "ACTIVE"]
        },

        "goal": {
          "type": "string"
        },

        "successCondition": {
          "type": "string"
        },

        "jitFieldDefinitions": {
          "type": "array",
          "description": "Fields not in coreFieldSchema. Empty array if none.",
          "items": {
            "type": "object",
            "required": ["fieldName", "type", "unitContract", "scope"],
            "properties": {
              "fieldName": {
                "type": "string",
                "description": "camelCase. No collisions with coreFieldSchema."
              },
              "type": {
                "type": "string",
                "enum": ["CURRENCY", "PERCENTAGE", "DURATION", "NUMBER", "BOOLEAN", "CHOICE"]
              },
              "unitContract": { "type": "string" },
              "parsingHint": { "type": "string", "nullable": true },
              "validation": { "type": "object", "nullable": true },
              "scope": {
                "type": "string",
                "enum": ["PLAN", "SCENARIO"]
              }
            }
          }
        },

        "steps": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["stepId", "action", "description", "userFacingDescription", "negotiable"],
            "properties": {

              "stepId": { "type": "string" },

              "phase": {
                "type": "string",
                "description": "From journeyTemplate. Null for scenarios.",
                "nullable": true
              },

              "action": {
                "type": "string",
                "enum": ["ASK_INPUT", "COMPUTE", "SHOW_RESULT", "RECOMMEND", "CONFIRM_ACTION"]
              },

              "description": {
                "type": "string",
                "description": "Execution instruction for subsequent turns. Tone cues, narration guidance."
              },

              "userFacingDescription": {
                "type": "string",
                "description": "Plain-language step summary for plan overview."
              },

              "whyNeeded": { "type": "string" },

              "negotiable": { "type": "boolean" },

              "requiredInputs": {
                "type": "array",
                "description": "ASK_INPUT only.",
                "nullable": true,
                "items": {
                  "type": "object",
                  "required": ["fieldName", "type", "whyNeeded"],
                  "properties": {
                    "fieldName": { "type": "string" },
                    "isJit": { "type": "boolean" },
                    "type": {
                      "type": "string",
                      "enum": ["CURRENCY", "PERCENTAGE", "DURATION", "NUMBER", "BOOLEAN", "CHOICE"]
                    },
                    "unitContract": { "type": "string" },
                    "whyNeeded": { "type": "string" },
                    "validation": { "type": "object", "nullable": true },
                    "sensitive": { "type": "boolean" }
                  }
                }
              },

              "toolChain": {
                "type": "array",
                "description": "COMPUTE only.",
                "nullable": true,
                "items": {
                  "type": "object",
                  "required": ["tool", "inputsFrom", "outputKey"],
                  "properties": {
                    "tool": { "type": "string" },
                    "inputsFrom": {
                      "type": "array",
                      "items": { "type": "string" }
                    },
                    "outputKey": { "type": "string" }
                  }
                }
              },

              "componentId": { "type": "string", "nullable": true },
              "componentDataMapping": { "type": "object", "nullable": true },

              "recommendation": {
                "type": "object",
                "nullable": true,
                "properties": {
                  "title": { "type": "string" },
                  "reasoning": { "type": "string" },
                  "actionItems": {
                    "type": "array",
                    "items": { "type": "string" }
                  }
                }
              },

              "consequenceLevel": {
                "type": "string",
                "enum": ["LOW", "MEDIUM", "HIGH"],
                "nullable": true
              },

              "guardrailRefs": {
                "type": "array",
                "nullable": true,
                "items": { "type": "string" }
              }
            }
          }
        }
      }
    },

    "planOverview": {
      "type": "object",
      "description": "High-level plan preview for user review. Emitted in MODE 1 (DRAFT) and MODE 2 (updated DRAFT or APPROVED). Null when not applicable.",
      "nullable": true,
      "properties": {
        "overviewId": {
          "type": "string",
          "description": "Descriptive slug: 'ef-overview-v1'"
        },
        "status": {
          "type": "string",
          "enum": ["DRAFT", "APPROVED"]
        },
        "goal": {
          "type": "string",
          "description": "What we're planning for"
        },
        "scopeNote": {
          "type": "string",
          "description": "What the plan covers and what the user gets. 1-2 sentences."
        },
        "phases": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "name": { "type": "string" },
              "steps": {
                "type": "array",
                "items": {
                  "type": "object",
                  "properties": {
                    "summary": {
                      "type": "string",
                      "description": "User-facing one-liner for this step"
                    },
                    "negotiable": { "type": "boolean" }
                  }
                }
              }
            }
          }
        }
      }
    },

    "goalObjectDraft": {
      "type": "object",
      "description": "Draft Goal Object for backend persistence. Null when no goal change.",
      "nullable": true,
      "properties": {

        "action": {
          "type": "string",
          "enum": ["CREATE", "UPDATE"],
          "description": "CREATE for new goals. UPDATE when goal properties change."
        },

        "goalRef": {
          "type": "string",
          "description": "For UPDATE: existing goal ID. For CREATE: null (backend assigns).",
          "nullable": true
        },

        "core": {
          "type": "object",
          "description": "Core fields. Include only what is known or changed.",
          "nullable": true,
          "properties": {
            "name": { "type": "string", "nullable": true },
            "type": {
              "type": "string",
              "enum": ["protection", "life_event", "wealth", "debt", "tax"],
              "nullable": true
            },
            "amount": {
              "type": "string",
              "nullable": true,
              "description": "Target amount as string with ₹ prefix"
            },
            "horizon": {
              "type": "string",
              "nullable": true,
              "description": "Temporal expression, freeform"
            },
            "tags": {
              "type": "array",
              "items": { "type": "string" },
              "nullable": true
            }
          }
        },

        "aiContext": {
          "type": "object",
          "description": "AI reasoning metadata. Include what is known.",
          "nullable": true,
          "properties": {
            "confidence": {
              "type": "string",
              "enum": ["low", "medium", "high"],
              "nullable": true
            },
            "negotiability": {
              "type": "string",
              "enum": ["fixed", "flex_amount", "flex_timeline", "fully_flexible"],
              "nullable": true
            },
            "assumptions": {
              "type": "array",
              "items": { "type": "string" },
              "nullable": true
            },
            "conflicts": {
              "type": "array",
              "items": { "type": "string" },
              "description": "Goal names or IDs",
              "nullable": true
            },
            "dependsOn": {
              "type": "array",
              "items": { "type": "string" },
              "description": "Goal names or IDs",
              "nullable": true
            },
            "notes": {
              "type": "array",
              "items": { "type": "string" },
              "nullable": true
            }
          }
        }
      }
    }
  }
}
